class Solution:
    def isPossibleToSplit(self, nums: List[int]) -> bool:
        from collections import Counter

        count = Counter(nums)

        # If any element appears more than twice, it's impossible to split
        # because we need two sets of equal size with distinct elements
        for freq in count.values():
            if freq > 2:
                return False

        return True
```

